$Encoding = New-Object Text.UTF8Encoding($false)
function Need($Value,[string]$Code) { if (-not $Value) { throw $Code } }
function HashBytes([byte[]]$Bytes) { $h=[Security.Cryptography.SHA256]::Create(); try { return [BitConverter]::ToString($h.ComputeHash($Bytes)).Replace('-','').ToLowerInvariant() } finally { $h.Dispose() } }
function PlainFile([string]$Path) { Need (Test-Path -LiteralPath $Path -PathType Leaf) 'FILE_MISMATCH'; Need (-not ((Get-Item -LiteralPath $Path).Attributes -band [IO.FileAttributes]::ReparsePoint)) 'FILE_MISMATCH' }
function WriteNew([string]$Path,[byte[]]$Bytes) { $f=[IO.File]::Open($Path,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None); try {$f.Write($Bytes,0,$Bytes.Length);$f.Flush($true)} finally {$f.Dispose()} }
function PrincipalSid($Task) {
  try { $u=[string]$Task.Definition.Principal.UserId; if ($u -match '^S-[0-9]+-') { return (New-Object Security.Principal.SecurityIdentifier($u)).Value }; return (New-Object Security.Principal.NTAccount($u)).Translate([Security.Principal.SecurityIdentifier]).Value } catch { return $null }
}
function ArgumentsFor([string]$Sha) {
  $runner='$p='''+$ScriptFile.Replace("'","''")+''';$b=[IO.File]::ReadAllBytes($p);$h=[Security.Cryptography.SHA256]::Create();try{$s=[BitConverter]::ToString($h.ComputeHash($b)).Replace(''-'','''').ToLowerInvariant()}finally{$h.Dispose()};if($s -cne '''+$Sha+'''){throw ''SCRIPT_SHA_MISMATCH''};& ([scriptblock]::Create([Text.Encoding]::UTF8.GetString($b))) -Mode Worker -SourceFile $p'
  return '-NoLogo -NoProfile -NonInteractive -Command "& { '+$runner+' }"'
}
function Matches($Task,[string]$Sha) {
  $d=$Task.Definition
  return ($d.RegistrationInfo.Description -ceq ('Ziwei one-shot '+$Sha) -and (PrincipalSid $Task) -ceq $Sid -and $d.Principal.LogonType -eq 3 -and $d.Principal.RunLevel -eq 0 -and $d.Actions.Count -eq 1 -and $d.Actions.Item(1).Path -ieq $PowerShell -and $d.Actions.Item(1).Arguments -ceq (ArgumentsFor $Sha) -and $d.Actions.Item(1).WorkingDirectory -ieq $Directory)
}
function OldTaskGuard($Task) {
  Need (Matches $Task $OldSha) 'TASK_MISMATCH'
  Need ([int]$Task.State -eq 3 -and [long]$Task.LastTaskResult -eq 1) 'TASK_NOT_FAILED_IDLE'
  Need (-not (Test-Path -LiteralPath $AttemptFile)) 'ATTEMPT_EXISTS'
}
try {
  Need ($env:OS -ceq 'Windows_NT') 'WINDOWS_ONLY'
  $Sid=[Security.Principal.WindowsIdentity]::GetCurrent().User.Value
  $PowerShell=Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
