  $planBytes=[IO.File]::ReadAllBytes($PlanFile);$planHash=HashBytes $planBytes;$planText=$Encoding.GetString($planBytes);$plan=$planText|ConvertFrom-Json
  Need ($plan.schemaVersion -eq 1 -and $plan.task -ceq $TaskName -and $plan.ownerSid -ceq $Sid -and $plan.scriptSha256 -ceq $OldSha -and $plan.expectedBuild -ceq $Build -and $plan.workspace -ceq 'bigtron' -and $plan.deviceId -ceq 'device_11af6d85-6c5c-4cbe-9a25-31599a474e5d' -and $plan.origin -ceq 'http://127.0.0.1:20242' -and ([string]$plan.root).TrimEnd('\') -ieq 'C:\Users\PC\AppData\Roaming\npm\node_modules\ziwei' -and $plan.configPath -ieq (Join-Path $env:LOCALAPPDATA 'Ziwei\ziwei_user\ziwei_user.json') -and $plan.userDirectory -ieq (Join-Path $env:LOCALAPPDATA 'Ziwei\ziwei_user')) 'PLAN_MISMATCH'
  $taskBytes=[Convert]::FromBase64String('')
  Need ((HashBytes $taskBytes) -ceq '74e1a307bb2902a3a7243b39735e86bb43fa4e4d50b345b27b52bf66f4e25953') 'HELPER_SHA_MISMATCH'
  $stopHelperBytes=[Convert]::FromBase64String('')
  Need ((HashBytes $stopHelperBytes) -ceq '3928e8490bf751aead4db35f556e79c5e66931e70003575126f6c246b391ebf8') 'HELPER_SHA_MISMATCH'
  $handleHelperBytes=[Convert]::FromBase64String('')
  Need ((HashBytes $handleHelperBytes) -ceq 'de27f9e0fe8eec94ab113141b3db1e46c1cb6bf48f92a45248a7b074d78110b2') 'HELPER_SHA_MISMATCH'
  $newBytes=$taskBytes
  $null=[scriptblock]::Create($Encoding.GetString($newBytes))
  $null=[scriptblock]::Create($Encoding.GetString($handleHelperBytes))
  Need ([regex]::Matches($planText,[regex]::Escape($OldSha)).Count -eq 1) 'PLAN_MISMATCH'
  $newPlanBytes=$Encoding.GetBytes($planText.Replace($OldSha,$NewSha));$newPlanHash=HashBytes $newPlanBytes
  # Final CAS before the first write. No task execution has been requested.
  $task=$Folder.GetTask($TaskName);OldTaskGuard $task
  Need ((HashBytes ($Encoding.GetBytes([string]$task.Xml))) -ceq $xmlHash -and (HashBytes ([IO.File]::ReadAllBytes($ScriptFile))) -ceq $OldSha -and (HashBytes ([IO.File]::ReadAllBytes($PlanFile))) -ceq $planHash) 'ORIGINAL_CHANGED'
  $Stage='backing_up'
  WriteNew $XmlBackup ($Encoding.GetBytes($oldXml));WriteNew $ScriptNext $newBytes;WriteNew $PlanNext $newPlanBytes
  WriteNew $StopHelperFile $stopHelperBytes;WriteNew $HandleHelperFile $handleHelperBytes
  Need ((HashBytes ([IO.File]::ReadAllBytes($StopHelperFile))) -ceq '3928e8490bf751aead4db35f556e79c5e66931e70003575126f6c246b391ebf8' -and (HashBytes ([IO.File]::ReadAllBytes($HandleHelperFile))) -ceq 'de27f9e0fe8eec94ab113141b3db1e46c1cb6bf48f92a45248a7b074d78110b2') 'HELPER_SHA_MISMATCH'
