  $allowed=@('FILE_MISMATCH','TASK_MISMATCH','EXPECTED_LITERAL_MISMATCH_ABSENT','TASK_NOT_FAILED_IDLE','ATTEMPT_EXISTS','WINDOWS_ONLY','SCRIPT_SHA_MISMATCH','ARCHIVE_EXISTS','PLAN_MISMATCH','HELPER_SHA_MISMATCH','ORIGINAL_CHANGED','POSTCHECK_UNKNOWN')
